import { test } from "node:test";
import assert from "node:assert/strict";
import type { AddressInfo } from "node:net";
import { createApp } from "../src/app.ts";

async function withServer(fn: (base: string, logs: string[]) => Promise<void>) {
  const logs: string[] = [];
  const server = createApp({ log: (line: string) => logs.push(line) });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
  const { port } = server.address() as AddressInfo;
  try {
    await fn(`http://127.0.0.1:${port}`, logs);
  } finally {
    await new Promise((r) => server.close(r));
  }
}

test("AC-9: GET /health returns 200 {status:ok}", async () => {
  await withServer(async (base) => {
    const res = await fetch(`${base}/health`);
    assert.equal(res.status, 200);
    assert.match(res.headers.get("content-type") ?? "", /application\/json/);
    assert.deepEqual(await res.json(), { status: "ok" });
  });
});

test("AC-10: unknown route returns JSON 404", async () => {
  await withServer(async (base) => {
    const res = await fetch(`${base}/nope`);
    assert.equal(res.status, 404);
    assert.match(res.headers.get("content-type") ?? "", /application\/json/);
    const body = (await res.json()) as { error: string };
    assert.equal(typeof body.error, "string");
  });
});

test("AC-11: wrong method on known route returns JSON 405 with Allow", async () => {
  await withServer(async (base) => {
    const res = await fetch(`${base}/health`, { method: "POST", body: "{}" });
    assert.equal(res.status, 405);
    assert.equal(res.headers.get("allow"), "GET");
    assert.match(res.headers.get("content-type") ?? "", /application\/json/);
    const body = (await res.json()) as { error: string };
    assert.equal(typeof body.error, "string");
  });
});

