import http from "node:http";

export interface AppOptions {
  log?: (line: string) => void;
}

type Handler = (req: http.IncomingMessage, res: http.ServerResponse) => void;

export function sendJson(res: http.ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "content-length": Buffer.byteLength(payload),
    ...headers,
  });
  res.end(payload);
}

// method -> handler, keyed by exact path
const routes: Record<string, Record<string, Handler>> = {
  "/health": { GET: (_req, res) => sendJson(res, 200, { status: "ok" }) },
};

function dispatch(req: http.IncomingMessage, res: http.ServerResponse): void {
  const path = new URL(req.url ?? "/", "http://localhost").pathname;
  const methods = routes[path];
  if (!methods) return sendJson(res, 404, { error: "not found" });
  const handler = methods[req.method ?? ""];
  if (!handler) return sendJson(res, 405, { error: "method not allowed" }, { allow: Object.keys(methods).join(", ") });
  handler(req, res);
}

