import { sendJson, type Handler } from "./http.ts";
import { notesHandlers } from "./notes.ts";
import { NoteStore } from "./store.ts";

export interface AppOptions {
  log?: (line: string) => void;
}

export { sendJson };

interface Route {
  pattern: RegExp;
  methods: Record<string, Handler>;
}

function buildRoutes(store: NoteStore): Route[] {
  const notes = notesHandlers(store);
  return [
    { pattern: /^\/health$/, methods: { GET: (_req, res) => sendJson(res, 200, { status: "ok" }) } },
    { pattern: /^\/notes$/, methods: { GET: notes.list, POST: notes.create } },
    { pattern: /^\/notes\/([^/]+)$/, methods: { GET: notes.get } },
  ];
}

async function dispatch(routes: Route[], req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
  const path = new URL(req.url ?? "/", "http://localhost").pathname;
  for (const { pattern, methods } of routes) {
    const m = pattern.exec(path);
    if (!m) continue;
    const handler = Object.hasOwn(methods, req.method ?? "") ? methods[req.method ?? ""] : undefined;
    if (!handler) return sendJson(res, 405, { error: "method not allowed" }, { allow: Object.keys(methods).join(", ") });
    let params: string[];
    try {
      params = m.slice(1).map(decodeURIComponent);
    } catch {
      return sendJson(res, 404, { error: "not found" });
    }
    return handler(req, res, params);
  }
  sendJson(res, 404, { error: "not found" });
}

export function createApp(options: AppOptions = {}): http.Server {
  const routes = buildRoutes(new NoteStore());
  const log = options.log ?? ((line: string) => console.log(line));
  return http.createServer((req, res) => {
    const start = process.hrtime.bigint();
    res.on("finish", () => {
      const ms = Number(process.hrtime.bigint() - start) / 1e6;
      const path = (req.url ?? "/").split("?")[0].replace(/[\r\n]/g, "");
      log(`${req.method} ${path} ${res.statusCode} ${ms.toFixed(1)}ms`);
    });
    dispatch(routes, req, res).catch(() => {
      if (!res.headersSent) sendJson(res, 500, { error: "internal server error" });
    });
  });
}
